const rawInput = $input.first().json;
const body = rawInput.body ? rawInput.body : rawInput;

if (!body.request_id) {
  return [{ json: {
    decision: 'BLOCKED',
    reason: 'MISSING_REQUEST_ID',
    message: 'request_id is required.'
  }}];
}

return [{ json: {
  request_id: body.request_id,
  decision: 'VALID_INPUT'
}}];

const approvalRaw = $input.first().json;
const prev = $('Payload Input Validator').first().json;
const approvalRow = Array.isArray(approvalRaw) ? (approvalRaw[0] || {}) : approvalRaw;
const approvalStatus = approvalRow.approval_status || '';

if (approvalStatus !== 'APPROVED_FOR_PAYLOAD_PREVIEW') {
  return [{ json: {
    request_id: prev.request_id,
    decision: 'BLOCKED',
    reason: 'APPROVAL_REQUIRED',
    message: 'This request has not been approved for payload preview. Current status: ' + (approvalStatus || 'not approved')
  }}];
}

return [{ json: {
  request_id: prev.request_id,
  decision: 'APPROVAL_CONFIRMED',
  approval_status: approvalStatus
}}];

const allInput = $input.all();
const prev = $('Restore After Approval Fetch').first().json;

if (prev.decision === 'BLOCKED') {
  return [{ json: prev }];
}

// Handle both possible n8n behaviors: the HTTP Request node may return the
// JSON array response as ONE item (item.json = [...]), or n8n may split it
// into multiple items (one item per array element, as we just confirmed
// happens here). Handle both robustly so this can't silently drop rows.
let rawItems = [];
if (allInput.length === 1 && Array.isArray(allInput[0].json)) {
  rawItems = allInput[0].json;
} else {
  rawItems = allInput.map(function(i) { return i.json; });
}

// Defensive filter: skip any row missing sku or asin — a NULL/blank
// database row should never reach the JSON_LISTINGS_FEED payload.
const items = rawItems.filter(function(item) {
  return item && item.sku && item.asin;
});

const skippedCount = rawItems.length - items.length;

return [{ json: {
  ...prev,
  items: items,
  skipped_invalid_items: skippedCount
}}];

const restored = $input.first().json;
if (restored.decision === 'BLOCKED') {
  return [{ json: restored }];
}

const CANONICAL_VALUES_MAP = {
  'extra small': 'XS',
  'small': 'S',
  'medium': 'M',
  'large': 'L',
  'extra large': 'XL',
  'extra extra large': 'XXL',
  'xxl': 'XXL'
};

function canonicalize(value) {
  if (value === undefined || value === null || value === '') return value;
  const trimmed = String(value).trim();
  const lower = trimmed.toLowerCase();
  if (CANONICAL_VALUES_MAP[lower]) return CANONICAL_VALUES_MAP[lower];
  return trimmed;
}

const items = restored.items || [];
const requestId = restored.request_id;
const parentSku = 'PARENT-' + requestId;
const brand = items[0]?.normalized_brand || 'UnknownBrand';
const productType = items[0]?.normalized_product_type || 'CLOTHING';
const variationStructure = restored.variation_structure || 'single_theme';
const matrixCells = restored.matrix_cells || null;
const validationErrors = [];

let themeName = restored.requested_variation_theme;
if (!themeName) {
  themeName = variationStructure === 'double_theme' ? 'ColorSize' : 'Color';
  validationErrors.push('No requested_variation_theme found -- defaulted to ' + themeName + '. Check merge_requests table for this request_id.');
}

const parentObject = {
  sku: parentSku,
  productType: productType,
  attributes: {
    parentage_level: [{ value: 'parent' }],
    child_relationship_type: [{ value: 'variation' }],
    variation_theme: [{ name: themeName }],
    brand: [{ value: brand }]
  }
};

let childObjects = [];

if (variationStructure === 'double_theme') {
  if (!matrixCells || !Array.isArray(matrixCells) || matrixCells.length === 0) {
    validationErrors.push('Double-theme request has no matrix cells in variation_matrices table. Cannot build payload.');
    return [{ json: {
      request_id: requestId,
      decision: 'BLOCKED',
      reason: 'MISSING_MATRIX_CELLS',
      message: 'No matrix cells found for this double-theme request. Run the validation workflow first to generate the matrix.',
      validation_errors: validationErrors,
      is_valid: false
    }}];
  }

  const seenCombinations = {};
  matrixCells.forEach(function(cell) {
    if (cell.status !== 'filled') return;
    const sizeVal = canonicalize(cell.size) || 'Unknown';
    const colorVal = canonicalize(cell.color) || 'Unknown';
    const combinationKey = sizeVal + '|' + colorVal;
    if (seenCombinations[combinationKey]) {
      validationErrors.push('Duplicate Size+Color combination: ' + sizeVal + ' / ' + colorVal + '. Cell: ' + cell.cell_id);
    }
    seenCombinations[combinationKey] = true;
    childObjects.push({
      sku: cell.sku,
      parentSku: parentSku,
      productType: productType,
      attributes: {
        parentage_level: [{ value: 'child' }],
        child_parent_sku_relationship: [{
          child_relationship_type: 'variation',
          parent_sku: parentSku
        }],
        brand: [{ value: brand }],
        size_name: [{ value: sizeVal }],
        color_name: [{ value: colorVal }]
      }
    });
  });

} else {
  // Day 17: dimension1_attribute now comes straight from merge_requests (written by
  // wf01's PTD Theme Validator from real Amazon theme data), instead of a hardcoded
  // Color/Size/Flavor -> attribute map that only ever understood the old made-up
  // theme names. Falls back to lowercasing the theme name itself for any older row
  // saved before this column was populated.
  const attributeKey = restored.dimension1_attribute || (themeName ? themeName.toLowerCase() : null);
  if (!attributeKey) {
    validationErrors.push('Could not determine the variation attribute for theme "' + themeName + '" -- dimension1_attribute is missing on this merge_requests row.');
  }
  childObjects = items.map(function(item) {
    const attributes = {
      parentage_level: [{ value: 'child' }],
      child_parent_sku_relationship: [{
        child_relationship_type: 'variation',
        parent_sku: parentSku
      }],
      brand: [{ value: brand }]
    };
    if (attributeKey) {
      attributes[attributeKey] = [{ value: canonicalize(item.variation_value) || 'Unknown' }];
    }
    return {
      sku: item.sku,
      parentSku: parentSku,
      productType: productType,
      attributes: attributes
    };
  });
}

const jsonPayload = {
  header: {
    sellerId: restored.seller_id || 'YOUR-SELLER-ID',
    version: '2.0',
    issueLocale: 'en_US'
  },
  body: {
    operationType: 'UPDATE',
    listings: [parentObject].concat(childObjects)
  }
};

return [{ json: {
  request_id: requestId,
  decision: 'PAYLOAD_READY',
  parent_sku: parentSku,
  child_count: childObjects.length,
  payload_type: 'JSON_LISTINGS_FEED',
  payload_status: 'PREVIEW_ONLY_NOT_SUBMITTED',
  json_payload: jsonPayload,
  validation_errors: validationErrors,
  is_valid: validationErrors.length === 0
}}];

const prev = $input.first().json;

if (prev.decision === 'BLOCKED') {
  return [{ json: prev }];
}

return [{ json: {
  _original_payload: prev,
  request_id: prev.request_id,
  payload_type: prev.payload_type || 'JSON_LISTINGS_FEED',
  payload_status: 'PREVIEW_ONLY_NOT_SUBMITTED',
  json_payload: JSON.stringify(prev.json_payload || {}),
  validation_result_json: JSON.stringify({ decision: prev.decision })
}}];

const restored = $('Restore After Items Fetch').first().json;

if (restored.decision === 'BLOCKED') {
  return [{ json: restored }];
}

const merge = $input.first().json || {};
let cells = merge.cells || null;

if (typeof cells === 'string') {
  try { cells = JSON.parse(cells); } catch(e) { cells = null; }
}

return [{ json: Object.assign({}, restored, {
  requested_variation_theme: merge.requested_variation_theme || null,
  variation_structure: merge.variation_structure || null,
  seller_id: merge.seller_id || null,
  dimension1_theme: merge.dimension1_theme || null,
  dimension1_attribute: merge.dimension1_attribute || null,
  dimension2_theme: merge.dimension2_theme || null,
  dimension2_attribute: merge.dimension2_attribute || null
}) }];

const restored = $('Restore After Merge Fetch').first().json;

if (restored.decision === 'BLOCKED') {
  return [{ json: restored }];
}

const matrixRow = $input.first().json || {};
let cells = matrixRow.cells || null;

if (typeof cells === 'string') {
  try { cells = JSON.parse(cells); } catch(e) { cells = null; }
}

return [{ json: Object.assign({}, restored, {
  matrix_cells: cells
}) }];
